+      state = (state * 16_807) % PARK_MILLER_MODULUS;
+      const value = state - 1;
+      if (value < limit) return value % bound;
+    }
+  };
+  for (let index = total - 1; index > 0; index -= 1) {
+    const other = draw(index + 1);
+    [deck[index], deck[other]] = [deck[other]!, deck[index]!];
+  }
+  return deck;
